struct Dsu {
    vector<int> p, rank_;
    explicit Dsu(int n) : p(n), rank_(n, 0) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) x = p[x] = p[p[x]];
        return x;
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (rank_[a] < rank_[b]) swap(a, b);
        p[b] = a;
        if (rank_[a] == rank_[b]) ++rank_[a];
        return true;
    }
};

signed main() {
    int t;
    cin >> t;
    while (t --> 0) {
        int n, m, q;
        cin >> n >> m >> q;
        vector<array<int, 3>> edges(m); // {d, u, v}
        int total = 0;
        for (int i = 0; i < m; i++) {
            int u, v, d;
            cin >> u >> v >> d;
            edges[i] = {d, u - 1, v - 1};
            total += d;
        }
        sort(edges.begin(), edges.end());

        Dsu dsu(n);
        vector<int> w;
        w.reserve(min(m, n - 1));
        for (auto &e : edges)
            if (dsu.unite(e[1], e[2])) w.push_back(e[0]);
        int top = w.size();
        vector<int> pref(top + 1, 0);
        for (int i = 0; i < top; i++) pref[i + 1] = pref[i] + w[i];

        for (int i = 0; i < q; i++) {
            int x;
            cin >> x;
            int lo = 0, hi = top;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (w[mid] - x * (n - mid - 1) >= 0) hi = mid;
                else lo = mid + 1;
            }
            int k = n - lo - 1;
            int cost = pref[lo] + x * (k * (k + 1) / 2);
            cout << total - cost << " ";
        }
        cout << endl;
    }
}

